const fs = require("fs");
const read = (f) => {
  if (!fs.existsSync(f)) { console.error("MISSING FILE: " + f); process.exit(1); }
  const raw = fs.readFileSync(f, "utf8").trim();
  const n = Number(raw);
  if (raw === "" || !Number.isFinite(n)) { console.error("NON-NUMERIC " + f + ": " + JSON.stringify(raw)); process.exit(1); }
  return n;
};
const seed = read("seed.txt");
const s1 = read("stage1.txt");
const s2 = read("stage2.txt");
const s3 = read("stage3.txt");
const checks = [
  ["stage1 == seed + 2", s1 === seed + 2],
  ["stage2 == stage1 * stage1", s2 === s1 * s1],
  ["stage3 == stage2 - 4", s3 === s2 - 4],
];
let ok = true;
for (const [name, pass] of checks) { console.log((pass ? "PASS" : "FAIL") + "  " + name); if (!pass) ok = false; }
if (!ok) { console.error("verification failed; answer.json not written"); process.exit(1); }
const answer = { stage1: s1, stage2: s2, stage3: s3 };
fs.writeFileSync("answer.json", JSON.stringify(answer, null, 2) + "\n");
console.log("verified from files: seed=" + seed + " stage1=" + s1 + " stage2=" + s2 + " stage3=" + s3);
