const fs=require("fs");
const fails=[];
const strict=(f)=>{
  if(!fs.existsSync(f)){fails.push("missing "+f);return NaN;}
  const raw=fs.readFileSync(f,"utf8");
  if(!/^-?\d+$/.test(raw.trim()) || raw.trim()===""){fails.push("not a strict integer in "+f+": "+JSON.stringify(raw));}
  return Number(raw.trim());
};
const seed=strict("seed.txt"), s1=strict("stage1.txt"), s2=strict("stage2.txt"), s3=strict("stage3.txt");
// independent recomputation from seed
const e1=seed+2, e2=e1*e1, e3=e2-4;
const eq=(name,a,b)=>{const ok=Object.is(a,b);console.log((ok?"PASS":"FAIL")+"  "+name+"  (actual="+a+", expected="+b+")");if(!ok)fails.push(name);};
eq("stage1 == seed+2", s1, e1);
eq("stage2 == stage1*stage1", s2, s2===s1*s1?s2:s1*s1);
eq("stage3 == stage2-4", s3, s3===s2-4?s3:s2-4);
